mapper.select:
SELECT TO_CHAR(t1.FYMD, 'YYYY-MM-DD') AS FYMD
     , t1.TT                          AS TT
  FROM USPM_PORT t1
 WHERE t1.CORP_GR  = #{corpGr}
   AND t1.FUND_CD  = #{fundCd}
   AND t1.PORT_NUM = #{portNum}
   AND t1.TYMD     = TO_DATE(#{ymd}, 'YYYY-MM-DD')
   AND ROWNUM = 1

SELECT DISTINCT t1.PORT_NUM
  FROM USPM_PORT t1
 WHERE t1.CORP_GR = #{corpGr}
   AND t1.FUND_CD = #{fundCd}
   AND t1.TYMD    = TO_DATE(#{ymd}, 'YYYY-MM-DD')
 ORDER BY t1.PORT_NUM ASC

SELECT NVL(MAX(col), 0)
  FROM USPM t1
 WHERE t1.CORP_GR  = #{corpGr}
   AND t1.FUND_CD  = #{fundCd}
   AND t1.YMD      = TO_DATE(#{ymd}, 'YYYY-MM-DD')
   AND t1.PORT_NUM = #{portNum}

SELECT COUNT(1)
  FROM USPM t1
 WHERE t1.CORP_GR  = #{corpGr}
   AND t1.FUND_CD  = #{fundCd}
   AND t1.YMD      = TO_DATE(#{ymd}, 'YYYY-MM-DD')
   AND t1.PORT_NUM = #{portNum}
   AND t1.JM_CD    = #{jmCd}
